// THE FINAL REHEARSAL — scene entry point.
// Static arena lives in assets/scene/main.composite (generated by `npm run arena`).
import { engine } from '@dcl/sdk/ecs'
import { SESSION } from './config'
import { createWatcher } from './boss/watcher'
import { initImprint } from './combat/imprint'
import { createTracerPool } from './effects/tracers'
import { state } from './game/state'
import { setupHud } from './ui/hud'

/** Single session clock. Runs first each frame; large hitches are clamped. */
function clockSystem(dt: number) {
  state.time += Math.min(dt, SESSION.maxFrameDt)
}

export function main() {
  engine.addSystem(clockSystem, 200000, "clock") // higher priority runs first (regular = 100000)
  createWatcher()
  createTracerPool()
  initImprint()
  setupHud()
  console.log('[FinalRehearsal] M1 loaded')
}
